<?php
 require_once(__DIR__.'/../../../init.php'); require_once('util/scheduler.php'); require_once('dicom/Dicom.php'); class med_common_dicom_exchange { const LOG = 'dicomExchange'; const SESSION_VAR = 'dicomExchange'; const TASK_NAME = 'medCommonDicomExchange'; const ACTION_REPLICATION = 1; const ACTION_REGISTRATION_LOG_STUDY = 2; const ACTIONS = [ 1 => 'Репликация', 2 => 'Регистрация в журнал исследований' ]; const STUDY_RESULT_STUDY_DATE = 'dicomStudyDate'; const STUDY_RESULT_CONCLUSION_DATE = 'dicomConclusionDate'; const STUDY_RESULT_CONCLUSION_HOUR = 'dicomConclusionHour'; const STUDY_RESULT_CONCLUSION_MINUTE = 'dicomConclusionMinute'; const STUDY_RESULT_DOCTOR = 'dicomDoctor'; const STUDY_RESULT_DESCRIPTION = 'dicomDescription'; const STUDY_RESULT_CONCLUSION = 'dicomConclusion'; const STUDY_RESULT_FIELDS = [ self::STUDY_RESULT_STUDY_DATE, self::STUDY_RESULT_CONCLUSION_DATE, self::STUDY_RESULT_DOCTOR, self::STUDY_RESULT_DESCRIPTION, self::STUDY_RESULT_CONCLUSION, ]; private $db; private $params; private $log; private $cancel = false; private $task; public function execute ($params = null) { $this->log = $log = new \Log(self::LOG, true); try { $this->params = $params ? $params : new \stdClass; setSessionValue(self::SESSION_VAR, null); $log->begin("Старт выполнения задач"); $log->info("Входные параметры:", false)->text(print_r($this->params, true), false); $this->doExecute(); $log->end("выполнение задач завершено"); $ret = ['success' => true]; if (isUndefinedProperty($this->params, 'htmlLog')) { $ret['htmlLog'] = $log->getHtml(); } return $ret; } catch (Throwable $e) { $log->error($e->getMessage(), false); throw $e; } } protected function doExecute () { $db = $this->db ?: $this->db = connectDb(); $log = $this->log; $params = $this->params; $serviceId = isEmptyProperty($params, 'serviceId', 0); $taskId = isEmptyProperty($params, 'taskId', 0); $forceExecute = isEmptyProperty($params, 'forceExecute', false); $now = new DateTime; $sql = <<<"EOT"
SELECT
    s.IncomingPort "srvPort",
    s.AE "srvAe",
    ((COALESCE(s.Attributes, 0) & 2) = 2) "extractResults",
    ((COALESCE(s.Attributes, 0) & 4) = 4) "extractImages",

    t.DicomTaskCode "taskId",
    t.Action "action",
    t.Periodicity "periodicity",
    t.Modalities "modalities",
    t.AccessionNumber "accessionNumber",
    t.LastRunTime "lastRunTime",
    t.SearchDepth "searchDepth",

    src.DicomPacsCode "srcId",
    src.Active "srcActive",
    src.Name "srcName",
    src.Host "srcHost",
    src.Port "srcPort",
    src.HttpPort "srcHttpPort",
    src.AE "srcAe",
    src.MethodGet "srcMethodGet",

    dst.DicomPacsCode "dstId",
    dst.Active "dstActive",
    dst.Name "dstName",
    dst.Host "dstHost",
    dst.Port "dstPort",
    dst.AE "dstAe"
FROM
    DicomTask t
    JOIN DicomService s ON
        s.DicomServiceCode = t.DicomServiceCode
        AND ((:serviceId = 0 AND s.Active = 1) OR (s.DicomServiceCode = :serviceId))
