$stmt = $db->prepare($sql); $stmt->execute([ ':serviceId' => $serviceId, ':taskId' => $taskId ]); while (($task = $stmt->fetch(PDO::FETCH_OBJ)) && !$this->isCancel()) { $this->task = $task; $task->name = $this->buildTaskName($task); $notActivePacs = ''; if (!$task->srcActive) { $notActivePacs .= " PACS источник \"$task->srcName\" отключен"; } if (!$notActivePacs && $task->action === self::ACTION_REPLICATION && !$task->dstActive) { $notActivePacs .= " PACS назначения \"$task->dstName\" отключен"; } if (!$notActivePacs && !$forceExecute && isset($task->lastRunTime)) { $launchTime = new DateTime($task->lastRunTime); $launchTime->modify("+{$task->periodicity} mins"); if ($launchTime > $now) { $notActivePacs .= " с предыдущего выполнения не прошло {$task->periodicity} мин"; continue; } } if ($notActivePacs) { $log->warning("Правило \"$task->name\" пропущено:$notActivePacs", false); continue; } $task->findDate = (new DateTime())->setTime(0, 0); if ($task->searchDepth && $task->searchDepth > 0) { $task->findDate->modify("-{$task->searchDepth} days"); } $db->beginTransaction(); try { $lock = selectSqlValue($db, "select pg_try_advisory_xact_lock('DicomTask'::regclass::int, ?)", [$task->taskId]); if ($lock) { $log->begin("Выполнение правила \"$task->name\""); switch ($task->action) { case self::ACTION_REPLICATION: $this->doReplication(); break; case self::ACTION_REGISTRATION_LOG_STUDY: $this->doRegistrationLogStudy(); break; } executeSql($db, "UPDATE DicomTask SET LastRunTime = now() WHERE DicomTaskCode = ?", [$task->taskId]); $log->end("Выполнение правила завершено"); } else { $log->info("Правило \"$task->name\" пропущено: уже выполняется в другом процессе"); } $db->commit(); } catch (Throwable $e) { $db->rollBack(); throw $e; } } } protected function doReplication () { $log = $this->log; $task = $this->task; $tempDir = realpath(sys_get_temp_dir()); $launchTime = microtime(true); $this->setStatus('загрузка объектов источника', 0, 3); $log->info("Загрузка объектов источника с {$task->findDate->format('d.m.Y')}..."); $query = new \Dicom\Item([ '0008,0052' => 'IMAGE', '0008,0050' => $task->accessionNumber ?: null, '0008,0060' => $task->modalities ?: null, '0008,0020' => $task->findDate->format('Ymd') . '-', '0008,0030' => null, '0010,0020' => null, '0020,000d' => null, '0020,000e' => null, '0008,0018' => null ]); $srcNet = new \Dicom\Net($task->srvAe, $task->srcAe, $task->srcHost, $task->srcPort, $task->srvPort); $srcObjects = $srcNet->findScu($query, 'study'); if ($srcObjects === false) { $log->error('Ошибка загрузки:')->text($srcNet->out); return; } $log->time("найдено " . count($srcObjects)); $this->setStatus('загрузка объектов назначения', 1, 3); $log->info("Загрузка объектов назначения..."); $dstNet = new \Dicom\Net($task->srvAe, $task->dstAe, $task->dstHost, $task->dstPort, $task->srvPort); $dstObjects = $dstNet->findScu($query, 'study'); if ($dstObjects === false) { $log->error('Ошибка загрузки:')->text($dstNet->out); return; } $log->time("найдено " . count($dstObjects)); $this->setStatus('синхронизация данных', 2, 3); $log->info("Синхронизация данных..."); $uids = []; foreach ($dstObjects as $obj) { $uids[$this->getObjectUid($obj)] = 1; } $missing = []; foreach ($srcObjects as $obj) { if (!isset($uids[$this->getObjectUid($obj)])) { $missing[] = $obj; } } $log->time("к перемещению объектов " . count($missing)); $query = new \Dicom\Item(['0008,0052' => 'IMAGE']); $moveTime = microtime(true); $commonSize = 0; $speedMbs = 0; $count = count($missing); for ($i = 0; $i < $count; ++$i) { if ($this->isCancel()) return; if (($deltaTime = (microtime(true) - $moveTime)) > 0.0) { $speedMbs = round($commonSize / 1024.0 / 1024.0 / $deltaTime, 2); } if ($i > 0) { $deltaTime = (microtime(true) - $launchTime); $secondPerImage = $deltaTime / $i; if (($deltaTime + $secondPerImage) > ($task->periodicity * 60.0)) { $log->info("Остановка по настройке длительности работы в {$task->periodicity} мин."); return; } } $speedText = $speedMbs > 0.0 ? ", {$speedMbs} мб/сек" : ""; $i1 = $i + 1; $speedText = " ($i1 из $count)$speedText"; $this->setStatus("перемещение объектов{$speedText}", $i * 2, $count * 2); $object = $missing[$i]; $uid = $object->get('0008,0018')->scalarValue(); $modality = $object->get('0008,0060')->scalarValue(); $log->info("<-- Загрузка [{$modality}.{$uid}]..."); $query->set('0010,0020', $object->get('0010,0020')->scalarValue()); $query->set('0020,000d', $object->get('0020,000d')->scalarValue()); $query->set('0020,000e', $object->get('0020,000e')->scalarValue()); $query->set('0008,0018', $uid); if ($task->srcMethodGet == 2) { if (!$srcNet->moveScu($query, 'study', $tempDir)) { $log->error('Ошибка загрузки (C-MOVE):')->text($srcNet->out); return; } } else { if (!$srcNet->getScu($query, 'study', $tempDir)) { $log->error('Ошибка загрузки (C-GET):')->text($srcNet->out); return; } } $log->time("ОК"); $files = glob("$tempDir/???.$uid"); if (empty($files)) { $log->error("Временный файл объекта не найден $tempDir/???.$uid"); continue; } $fileName = $files[0]; try { if ($this->isCancel()) return; $fileSize = filesize($fileName); $commonSize += $fileSize; $fileSize = humanFileSize($fileSize); $log->add("$fileName ($fileSize) ОК", false); $this->setStatus("перемещение объектов{$speedText}", $i * 2 + 1, $count * 2); $log->info("--> Сохранение..."); if (!$dstNet->storeScu($fileName)) { $log->error('Ошибка передачи:')->text($dstNet->out); return; } $log->time("ОК"); } finally { $log->info("Удаление файла снимка...", false); if (unlink($fileName) === false) { $log->error("Ошибка удаления временного файла $fileName"); } else { $log->add("ОК", false); } } } } protected function doRegistrationLogStudy () { $db = $this->db ?: $this->db = connectDb(); $log = $this->log; $task = $this->task; $extractResults = isUndefinedProperty($task, 'extractResults', false); $extractImages = isUndefinedProperty($task, 'extractImages', false); $sqlSelectInstance = <<<"EOT"
SELECT
    mls.MedLogStudyCode "medLogStudyCode",
