$stmtCreateInstance = $db->prepare($sqlCreateInstance); $log->info("Загрузка списка объектов с {$task->findDate->format('d.m.Y')}..."); $query = new \Dicom\Item(); $query->setElements([ '0008,0052' => 'IMAGE', '0008,0050' => $task->accessionNumber ?: null, '0008,0060' => $task->modalities ?: null, '0008,0020' => $task->findDate->format('Ymd') . '-', '0008,0030' => null, '0008,0012' => null, '0008,0013' => null, '0008,0023' => null, '0008,0033' => null, '0010,0020' => null, '0010,4000' => null, '0020,000d' => null, '0020,000e' => null, '0008,0018' => null, '0008,0016' => null, '0020,0011' => null, '0020,0013' => null ]); $srcNet = new \Dicom\Net($task->srvAe, $task->srcAe, $task->srcHost, $task->srcPort, $task->srvPort); $objects = $srcNet->findScu($query, 'study'); if ($objects === false) { $log->error('Ошибка поиска:')->text($srcNet->out); return; } $log->time("найдено объектов " . count($objects)); $countAdd = 0; $countUpdate = 0; $countException = 0; foreach ($objects as $obj) { $fieldsExists = false; $studyImageInfo = null; $studyImageFilePath = null; $db->beginTransaction(); try { $uid = $obj->get('0008,0018')->scalarValue(); $modality = $obj->get('0008,0060')->scalarValue(); $accessNumber = $obj->get('0008,0050')->scalarValue(); $log->info("Обработка [{$modality}.{$uid}; AN:$accessNumber]...", false); if (!preg_match('/\\d+$/', $accessNumber, $matches)) { $log->error("Ошибка в атрибуте AccessNumber $accessNumber", false); $db->rollBack(); continue; } $medLogStudyCode = (int)$matches[0]; $createTime = $this->getDicomDateTime($obj, '0008,0020', '0008,0030'); if (!$createTime) { $log->error("Ошибка в дате и времени исследования", false); $db->rollBack(); continue; } $stmtSelectInstance->execute([$uid, $medLogStudyCode]); $row = $stmtSelectInstance->fetch(PDO::FETCH_OBJ); if (empty($row)) { $log->error("В базе отсутствует иследование $medLogStudyCode", false); } else if (empty($row->medLogStudySopCode)) { $studyInstanceUID = $obj->get('0020,000d')->scalarValue(); if ($extractResults) { $fieldsExists = $this->checkExistenceOfComponentFields($db, $row->htmPageCode, self::STUDY_RESULT_FIELDS); if ($fieldsExists) { $studyInfo = $this->fetchStudyInfo($studyInstanceUID, $task->srcHost, $task->srcHttpPort); } $studyImageInfo = $this->fetchStudyImageInfo($uid, $task->srcHost, $task->srcHttpPort); } if ($extractImages) { $studyImageFilePath = $this->fetchStudyImageFile($uid, $task->srcHost, $task->srcHttpPort); } $stmtCreateInstance->execute([ ':MedLogStudyCode' => $medLogStudyCode, ':DicomPacsCode' => $task->srcId, ':PatientID' => $obj->get('0010,0020')->scalarValue(), ':StudyInstanceUID' => $studyInstanceUID, ':StudyTime' => dbDateTime($createTime), ':AccessionNumber' => $accessNumber, ':SeriesInstanceUID' => $obj->get('0020,000e')->scalarValue(), ':SeriesNumber' => $obj->get('0020,0011')->scalarValue(), ':Modality' => $modality, ':SOPInstanceUID' => $uid, ':InstanceNumber' => $obj->get('0020,0013')->scalarValue(), ':JSON' => !empty($studyImageInfo) ? json_encode(['image' => $studyImageInfo]) : null, ':imageFileName' => !empty($studyImageFilePath) ? $studyImageFilePath : null, ]); if ($extractResults) { if ($fieldsExists && !empty($studyInfo)) { try { $this->saveStudyInfo($db, $row->htmPageCode, $studyInfo); } catch (\Exception $e) { ++$countException; $log->error("Ошибка сохранения результата из DICOM в компонент назначения: " . $e->getMessage(), false); } } if (!$fieldsExists) { ++$countException; $log->error('В направлении "' . $medLogStudyCode . '" отстутствуют необходимые поля: ' . implode(', ', self::STUDY_RESULT_FIELDS) . '.', false); } } ++$countAdd; $log->time("добавлено", false); } else { $log->time("существует", false); } $stmtSelectInstance->closeCursor(); $db->commit(); } catch (Throwable $e) { $db->rollBack(); ++$countException; $log->error("Неизвестная ошибка " . $e->getMessage(), false); } } if ($countAdd) { $log->info("Добавлено объектов $countAdd"); } if ($countUpdate) { $log->info("Обновлено объектов $countUpdate"); } if ($countException) { $log->error("Неизвестных ошибок $countException"); } } public function getStatus ($isCancel = false) { if ($isCancel) { setSessionValue(self::SESSION_VAR, ['cancel' => true]); return true; } return getSessionValue(self::SESSION_VAR); } public function testScheduler () { $settings = readExtraSettings(null, self::TASK_NAME); return !empty($settings->scheduleActive); } public function setupScheduler ($active) { $settings = readExtraSettings(null, self::TASK_NAME); Scheduler::writeExtraSettings(null, self::TASK_NAME, (object)[ 'scheduleUUID' => isUndefinedProperty($settings, 'scheduleUUID'), 'scheduleActive' => $active, 'scheduleScript' => 'app/med/common/dicom/exchange.php', 'scheduleMethod' => 'execute', 'scheduleType' => 'minute', 'schedulePeriodicity' => 5 ], true); return true; } protected function setStatus ($text, $progress, $count) { setSessionValue(self::SESSION_VAR, [ 'name' => "{$this->task->name}: $text...", 'count' => $count, 'progress' => $progress ]); } protected function isCancel () { if (!$this->cancel) { reloadSession(); $var = getSessionValue(self::SESSION_VAR); if (isset($var['cancel']) && $var['cancel']) { $this->cancel = true; $this->log->info("Прервано пользователем!"); } } return $this->cancel; } protected static function buildTaskName ($task) { $m = $task->modalities ? ' '.$task->modalities : ''; $res = self::ACTIONS[$task->action] . "$m '$task->srcName'"; if ($task->action === 1) { $res .= " -> '" . $task->dstName . "'"; } return $res; } protected static function getObjectUid ($object) { return $object->get('0010,0020')->scalarValue() . '-' . $object->get('0020,000d')->scalarValue() . '-' . $object->get('0020,000e')->scalarValue() . '-' . $object->get('0008,0018')->scalarValue(); } protected static function getDicomDateTime ($object, $attrDate, $attrTime) { $s = $object->get($attrDate)->scalarValue() . $object->get($attrTime)->scalarValue(); return date_create_from_format('YmdHis', substr($s, 0, 14)); } protected function fetchStudyInfo($studyInstanceUID, $host, $port) { $result = (object)[ 'studyDate' => null, 'description' => null, 'conclusion' => null, 'doctors' => null, 'conclusionDate' => null, 'conclusionTime' => null, ]; $apiUrl = 'http://' . $host . ':' . $port; $instanceIDs = $this->httpJsonFetch($apiUrl . '/tools/find', [ 'Level' => 'Instance', 'Query' => [ 'StudyInstanceUID' => $studyInstanceUID, 'Modality' => 'SR', ], ]); if (empty($instanceIDs)) return null; $instances = []; foreach ($instanceIDs as $id) { $instanceInfo = $this->httpJsonFetch($apiUrl . '/instances/' . $id . '/simplified-tags'); if (!empty($instanceInfo)) { $instances[] = $instanceInfo; } } if (count($instances) > 1) { usort($instances, function($a, $b) { $diff = strcmp(@$b['ContentDate'], @$a['ContentDate']); return ($diff !== 0) ? $diff : strcmp(@$b['ContentTime'], @$a['ContentTime']); }); } $instance = !empty($instances) ? $instances[0] : null; if (!empty($instance)) { $result->studyDate = parseDicomDate( @$instance['StudyDate'] ); $result->conclusionDate = parseDicomDate( @$instance['ContentDate'] ); $result->conclusionTime = parseDicomTime( @$instance['ContentTime'] ); $result->doctors = $this->collectDoctors($instance); $result->description = $this->fetchContentTag($apiUrl . '/instances/' . $id, $instance, 121060); $result->conclusion = $this->fetchContentTag($apiUrl . '/instances/' . $id, $instance, 121076); } $isEmptyResult = empty($result->studyDate) && empty($result->description) && empty($result->conclusion) && empty($result->doctors) && empty($result->conclusionDate) && empty($result->conclusionTime); return !$isEmptyResult ? $result : null; } protected function saveStudyInfo($db, $htmPageCode, $studyInfo) { if (!empty($studyInfo->studyDate)) { $studyDateStr = $studyInfo->studyDate->format('d.m.Y'); $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_STUDY_DATE, $studyDateStr); } if (!empty($studyInfo->conclusionDate)) { $conclusionDateStr = $studyInfo->conclusionDate->format('d.m.Y'); $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_CONCLUSION_DATE, $conclusionDateStr); } if (!empty($studyInfo->conclusionTime)) { if ($this->checkExistenceOfComponentFields($db, $htmPageCode, [self::STUDY_RESULT_CONCLUSION_HOUR, self::STUDY_RESULT_CONCLUSION_MINUTE])) { $conclusionHourStr = $studyInfo->conclusionTime->format('G'); $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_CONCLUSION_HOUR, $conclusionHourStr); $conclusionMinuteStr = $studyInfo->conclusionTime->format('i'); $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_CONCLUSION_MINUTE, $conclusionMinuteStr); } } $doctorNames = $this->getDoctorNames($db, $studyInfo->doctors); if (!empty($doctorNames)) { $doctorCiphers = array_map( function($v) { return strval($v); }, $studyInfo->doctors ); $doctorEntry = json_encode([ 'code' => $doctorCiphers, 'displayValue' => $doctorNames, ]); $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_DOCTOR, $doctorEntry, true); } if (!empty($studyInfo->description)) { $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_DESCRIPTION, $studyInfo->description, true); } if (!empty($studyInfo->conclusion)) { $this->updateComponentValue($db, $htmPageCode, self::STUDY_RESULT_CONCLUSION, $studyInfo->conclusion, true); } } protected function fetchStudyImageInfo($sopInstanceUID, $host, $port) { $excludeModalities = [ 'SR', ]; $result = null; $apiUrl = 'http://' . $host . ':' . $port; $instanceIDs = $this->httpJsonFetch($apiUrl . '/tools/find', [ 'Level' => 'Instance', 'Query' => [ 'SOPInstanceUID' => $sopInstanceUID, ], ]); if (empty($instanceIDs)) return null; $instances = []; foreach ($instanceIDs as $id) { $instanceInfo = $this->httpJsonFetch($apiUrl . '/instances/' . $id . '/simplified-tags'); if (!empty($instanceInfo)) { if (isset($instanceInfo['Modality'])) { if (array_search($instanceInfo['Modality'], $excludeModalities) !== false) { continue; } } $instances[] = $instanceInfo; } } $instance = (count($instances) > 0) ? $instances[0] : null; if (!empty($instance) && isset($instance['SOPInstanceUID']) && isset($instance['SOPClassUID']) && isset($instance['SpecificCharacterSet']) && isset($instance['SeriesInstanceUID']) && isset($instance['Modality']) && isset($instance['StudyID']) && isset($instance['StudyDate']) ) { $result = new DICOMImageInfo( $instance['SOPInstanceUID'], $instance['SOPClassUID'], $instance['SpecificCharacterSet'], $instance['ImageType'] ?? null, new DICOMImageSeriesInfo( $instance['SeriesInstanceUID'], $instance['Modality'], $instance['SeriesDate'] ?? null, $instance['SeriesTime'] ?? null, $instance['SourceApplicationEntityTitle'] ?? null, ), new DICOMImageStudyInfo( $instance['StudyID'], $instance['StudyDate'], $instance['StudyTime'] ?? null, $instance['StudyDate'] ?? null, $instance['StudyTime'] ?? null, ), ); } return $result; } protected function fetchStudyImageFile($sopInstanceUID, $host, $port) { $excludeModalities = [ 'SR', ]; $result = null; $apiUrl = 'http://' . $host . ':' . $port; $instanceIDs = $this->httpJsonFetch($apiUrl . '/tools/find', [ 'Level' => 'Instance', 'Query' => [ 'SOPInstanceUID' => $sopInstanceUID, ], ]); if (empty($instanceIDs)) return null; $instances = []; foreach ($instanceIDs as $id) { $instanceInfo = $this->httpJsonFetch($apiUrl . '/instances/' . $id . '/simplified-tags'); if (!empty($instanceInfo)) { if (isset($instanceInfo['Modality'])) { if (array_search($instanceInfo['Modality'], $excludeModalities) !== false) { continue; } } $instanceInfo['_InstanceID'] = $id; $instances[] = $instanceInfo; } } $instance = (count($instances) > 0) ? $instances[0] : null; if (!empty($instance)) { $image = $this->httpImageFetch($apiUrl . '/instances/' . $instance['_InstanceID'] . '/preview'); $imageGUID = $instance['_InstanceID']; if ($imageGUID != null) { $storage = new map_common_storage(); $fileName = "dicom-images/" . mb_substr($imageGUID, 0, 1) . "/" . mb_substr($imageGUID, 1, 2) . "/" . $imageGUID . ".jpg"; $storage->writeFile(2, $fileName, $image); $result = $fileName; } } return $result; } protected function getDoctorNames($db, $ciphers) { if (!empty($ciphers)) { $placeholders = implode(', ', array_fill(0, count($ciphers), '?')); $sql = <<<EOT
